-- Executed after the canonical TEXT rollback QA defines pg_temp.qa_queue_post.
-- The only READY source below is explicitly synthetic rollback-only metadata:
-- no provider, media bytes, customer message or social publication is involved.
DO $video_publication_qa$
DECLARE b uuid; target uuid; post uuid; video uuid; job uuid; claim uuid; cid uuid:=gen_random_uuid();
 p jsonb; v jsonb; cmd jsonb; saved jsonb; result jsonb; artifact jsonb; sent jsonb; denied boolean;
BEGIN
 p:=pcs.content_action('brand',jsonb_build_object('request_id',gen_random_uuid(),'name','QA synthetic video publication rollback','guidelines','Synthetic rollback acceptance only. Never publish any material.'),'pcs-manager-admin','["*"]');b:=(p#>>'{brand,id}')::uuid;
 p:=pcs.content_target_action(jsonb_build_object('request_id',gen_random_uuid(),'brand_id',b,'username','qa_video_pub_rollback'),'pcs-manager-admin','["*"]','{"username":"qa_video_pub_rollback","chat_id":"-100111222334","bot_id":"123456789","title":"Synthetic video target, no transport","can_post_messages":true}');target:=(p->>'id')::uuid;
 p:=pg_temp.qa_queue_post(b);post:=(p->>'id')::uuid;
 v:=pcs.content_video_action('create',jsonb_build_object('request_id',gen_random_uuid(),'post_id',post,'expected_post_version',p->'version','revision',1,'confirmed',true,'upscale_confirmed',true,'spec','{"version":1,"mode":"TEXT_TO_VIDEO","preset":"landscape","fit":"contain","shots":[{"prompt":"A synthetic green leaf fixture, no GPU call.","negative_prompt":"text","seed":42,"frames":17}]}'::jsonb),'pcs-manager-admin','["*"]');video:=(v#>>'{job,id}')::uuid;
 artifact:=jsonb_build_object('bucket','pcs-content-video','path','jobs/'||video||'/'||cid||'/final.mp4','sha256',repeat('a',64),'bytes',4096,'width',1280,'height',720,'fps',24,'frames',51,'duration_seconds',2.125,'decode_verified',true,'codec','h264','technical_qa','PASSED','manual_review_required',true,'cover',jsonb_build_object('bucket','pcs-content-video','path','jobs/'||video||'/'||cid||'/cover.png','sha256',repeat('b',64),'bytes',100),'source_model','Lightricks/LTX-Video-0.9.5','model_revision','e58e28c39631af4d1468ee57a853764e11c1d37e','manifest_sha256',repeat('c',64));
 UPDATE public.pcs_workflow_outbox SET status='SENT',sent_at=clock_timestamp(),payload=payload||jsonb_build_object('stage','READY','claim_id',cid,'artifact',artifact,'version',2) WHERE id=video;
 v:=pcs.content_video_action('review',jsonb_build_object('request_id',gen_random_uuid(),'job_id',video,'expected_version',2,'confirmed',true,'decision','APPROVED','artifact_sha256',repeat('a',64),'note','Explicit synthetic rollback metadata acceptance, never real media approval.'),'pcs-manager-admin','["*"]');
 cmd:=jsonb_build_object('request_id',gen_random_uuid(),'id',post,'expected_version',p->'version','target_id',target,'target_version',1,'scheduled_at',to_char(timezone('UTC',clock_timestamp()+interval '1 day'),'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'publication_confirmed',true,'video_job_id',video,'video_version',v#>'{job,version}','artifact_sha256',repeat('a',64),'video_confirmed',true);
 saved:=pcs.content_publication_action('schedule-video',cmd,'pcs-manager-admin','["*"]');job:=(saved#>>'{job,id}')::uuid;
 IF saved#>>'{job,media_kind}'<>'VIDEO' OR saved#>'{job,video_snapshot,artifact}' IS DISTINCT FROM artifact OR saved#>>'{job,video_snapshot,id}'<>video::text THEN RAISE EXCEPTION 'QA video source freeze failed';END IF;
 IF pcs.content_publication_action('schedule-video',cmd,'pcs-manager-admin','["*"]')->>'replayed'<>'true' THEN RAISE EXCEPTION 'QA video schedule replay failed';END IF;
 denied:=false;BEGIN UPDATE pcs.content_publication_jobs SET video_snapshot=NULL WHERE id=job;EXCEPTION WHEN check_violation THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA NULL video snapshot allowed';END IF;
 -- Explicit rejection before dispatch invalidates the queued frozen source.
 v:=pcs.content_video_action('review',jsonb_build_object('request_id',gen_random_uuid(),'job_id',video,'expected_version',3,'confirmed',true,'decision','REJECTED','artifact_sha256',repeat('a',64),'note','Synthetic source rejected before transport to exercise stale claim.'),'pcs-manager-admin','["*"]');
 UPDATE pcs.content_publication_jobs SET scheduled_at=clock_timestamp()-interval '1 minute' WHERE id=job;
 result:=pcs.content_claim_publication();IF result->'job'<>'null'::jsonb OR result->>'blocked_job_id'<>job::text OR NOT EXISTS(SELECT 1 FROM pcs.content_publication_jobs WHERE id=job AND state='BLOCKED' AND last_error='video_changed') THEN RAISE EXCEPTION 'QA rejected source was dispatched';END IF;
 v:=pcs.content_video_action('review',jsonb_build_object('request_id',gen_random_uuid(),'job_id',video,'expected_version',4,'confirmed',true,'decision','APPROVED','artifact_sha256',repeat('a',64),'note','Explicit second synthetic rollback approval after blocked dispatch.'),'pcs-manager-admin','["*"]');
 cmd:=cmd||jsonb_build_object('request_id',gen_random_uuid(),'expected_version',(SELECT version FROM pcs.content_posts WHERE id=post),'video_version',5);
 saved:=pcs.content_publication_action('schedule-video',cmd,'pcs-manager-admin','["*"]');IF saved#>>'{job,id}'<>job::text THEN RAISE EXCEPTION 'QA video reschedule allocated duplicate';END IF;
 UPDATE pcs.content_publication_jobs SET scheduled_at=clock_timestamp()-interval '1 minute' WHERE id=job;
 result:=pcs.content_claim_publication();claim:=(result#>>'{job,claim_id}')::uuid;IF result#>>'{job,id}'<>job::text OR claim IS NULL THEN RAISE EXCEPTION 'QA video claim failed';END IF;
 denied:=false;BEGIN PERFORM pcs.content_video_action('review',jsonb_build_object('request_id',gen_random_uuid(),'job_id',video,'expected_version',5,'confirmed',true,'decision','REJECTED','artifact_sha256',repeat('a',64),'note','Must not change frozen source during an external send.'),'pcs-manager-admin','["*"]');EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA SENDING video review changed';END IF;
 sent:=jsonb_build_object('outcome','SENT','chat_id','-100111222334','caption','Approved queue fixture text','message_id','91','date',floor(extract(epoch FROM clock_timestamp()))::bigint,'artifact_sha256',repeat('a',64),'video',jsonb_build_object('file_id','synthetic-provider-file','file_unique_id','synthetic-unique-file','width',1280,'height',720,'duration',2,'file_size',NULL));
 denied:=false;BEGIN PERFORM pcs.content_complete_publication(job,claim,sent||jsonb_build_object('artifact_sha256',repeat('b',64)));EXCEPTION WHEN invalid_parameter_value THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA wrong uploaded source receipt accepted';END IF;
 result:=pcs.content_complete_publication(job,claim,sent);IF result#>>'{job,state}'<>'SENT' OR result#>>'{job,public_url}'<>'https://t.me/qa_video_pub_rollback/91' THEN RAISE EXCEPTION 'QA video receipt not saved';END IF;
 IF pcs.content_complete_publication(job,claim,sent)->>'replayed'<>'true' THEN RAISE EXCEPTION 'QA video receipt replay failed';END IF;
 denied:=false;BEGIN PERFORM pcs.content_video_action('review',jsonb_build_object('request_id',gen_random_uuid(),'job_id',video,'expected_version',5,'confirmed',true,'decision','REJECTED','artifact_sha256',repeat('a',64),'note','Must not change the source represented by a saved receipt.'),'pcs-manager-admin','["*"]');EXCEPTION WHEN serialization_failure THEN denied:=true;END;IF NOT denied THEN RAISE EXCEPTION 'QA SENT video review changed';END IF;
 IF pcs.content_claim_publication()->'job'<>'null'::jsonb THEN RAISE EXCEPTION 'QA completed video was dispatched twice';END IF;
END $video_publication_qa$;
